function filtered(){const f=$('#from').value,t=$('#to').value,s=$('#sale').value;return data.Orders.filter(o=>o.Date>=f&&o.Date<=t&&(s==='Tất cả'||o.Owner===s));}
function kpi(rows){const r=rows.filter(x=>x.Status==='Hoàn'||x.Status==='Hủy'),ok=rows.filter(x=>x.Status!=='Hoàn'&&x.Status!=='Hủy'),n=rows.filter(x=>x.Type==='Khách mới'),o=rows.filter(x=>x.Type==='Khách cũ');return{n,o,r,newRev:sum(n,'Amount'),oldRev:sum(o,'Amount'),returnRev:sum(r,'Amount'),revenue:sum(ok,'Amount')}}
function aggregateKpi(items){const n=Array(Math.max(0,Math.round(sum(items,'NewOrders')))).fill(0),o=Array(Math.max(0,Math.round(sum(items,'OldOrders')))).fill(0),r=Array(Math.max(0,Math.round(sum(items,'ReturnCount')))).fill(0);return {n,o,r,newRev:sum(items,'NewRevenue'),oldRev:sum(items,'OldRevenue'),returnRev:sum(items,'ReturnRevenue'),revenue:sum(items,'NetRevenue')}}
