 $('#chart').innerHTML=chartDays.map(d=>{const q=dayKpi(d);return `<div class="bar-group"><i class="bar new" style="height:${q.newRev/max*100}%"></i><i class="bar old" style="height:${q.oldRev/max*100}%"></i><i class="bar return" style="height:${q.returnRev/max*100}%"></i><b class="bar-label">${d.slice(8)}/${d.slice(5,7)}</b></div>`}).join('');
 const sales=useSummary?[...new Set(data.ExternalSummary.BySale.map(x=>x.Owner))]:[...new Set(data.Orders.map(x=>x.Owner))],stats=(useSummary?sales.map(name=>{const v=data.ExternalSummary.BySale.filter(x=>x.Owner===name&&x.Date>=f&&x.Date<=t);return {name,k:{...aggregateKpi([]),newRev:sum(v,'NewRevenue'),oldRev:sum(v,'OldRevenue'),revenue:sum(v,'NetRevenue')},lead:0}}):sales.map(name=>({name,rows:rows.filter(x=>x.Owner===name)})).map(x=>({...x,k:kpi(x.rows),lead:data.Customers.filter(c=>c.Owner===x.name&&c.Created>=f&&c.Created<=t).length}))).sort((a,b)=>b.k.revenue-a.k.revenue),top=Math.max(1,...stats.map(x=>x.k.revenue));
