 const dailyPager=$('#daily-pagination');if(dailyPager)dailyPager.innerHTML=Array.from({length:totalDailyPages},(_,i)=>`<button class="${i+1===dailyPage?'active':''}" data-daily-page="${i+1}">${i+1}</button>`).join('');
