function renderCustomers(){const q=($('#customer-search').value||'').toLowerCase();const rows=data.Customers.filter(x=>!q||x.Name.toLowerCase().includes(q)||x.Phone.includes(q));$('#customers-table').innerHTML='<tr><th>Khách hàng</th><th>Số điện thoại</th><th>Nguồn</th><th>Sale phụ trách</th><th>Ngày tạo</th><th>Ghi chú</th></tr>'+rows.sort((a,b)=>b.Created.localeCompare(a.Created)).map(x=>`<tr><td><button class="customer-link customer-profile" data-phone="${x.Phone}">${x.Name}</button></td><td>${x.Phone}</td><td>${x.Source||'—'}</td><td>${x.Owner}</td><td>${x.Created}</td><td>${x.Note||'—'}</td></tr>`).join('')}
