function save(message){window.vitagreen.saveData(data).then(()=>toast(message||'Đã lưu dữ liệu thành công'))}
function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2800)}
function openNotice(index){const n=window.currentNotices?.[index];if(!n)return;$('#modal-title').textContent=n.title;$('#modal-form').innerHTML=`<div class="notice-detail"><div class="label">Chỉ số</div><div>${n.metric}</div><div class="label">Kết quả hiện tại</div><div>${n.value}</div><div class="label">Mốc đánh giá</div><div>${n.target}</div><div class="label">Nhận định</div><div>${n.text}</div><div class="label">Giải pháp đề xuất</div><div>${n.solution}</div></div>`;$('#modal').classList.remove('hidden')}
function reportRange(){return {from:$('#report-from').value,to:$('#report-to').value}}
function renderCustomerReport(page=1){const {from,to}=reportRange(),sort=$('#customer-sort').value,orders=data.Orders.filter(x=>x.Date>=from&&x.Date<=to&&x.Status==='Thành công'),map=new Map();orders.forEach(o=>{const key=o.CustomerPhone||o.CustomerName;const item=map.get(key)||{name:o.CustomerName,phone:o.CustomerPhone,orders:0,revenue:0,first:o.Date,last:o.Date};item.orders++;item.revenue+=+o.Amount||0;if(o.Date<item.first)item.first=o.Date;if(o.Date>item.last)item.last=o.Date;map.set(key,item)});const rows=[...map.values()];if(sort==='revenue-desc')rows.sort((a,b)=>b.revenue-a.revenue);else if(sort==='revenue-asc')rows.sort((a,b)=>a.revenue-b.revenue);else rows.sort((a,b)=>b.last.localeCompare(a.last));const perPage=10,pages=Math.max(1,Math.ceil(rows.length/perPage)),current=Math.min(Math.max(1,page),pages),shown=rows.slice((current-1)*perPage,current*perPage);$('#report-customers-table').innerHTML='<tr><th>#</th><th>Khách hàng</th><th>Số điện thoại</th><th>Số đơn thành công</th><th>Doanh thu</th><th>Phát sinh gần nhất</th></tr>'+shown.map((x,i)=>`<tr><td>${(current-1)*perPage+i+1}</td><td><button class="customer-link" data-phone="${x.phone||''}" data-name="${encodeURIComponent(x.name)}">${x.name||'Chưa có tên'}</button></td><td>${x.phone||'—'}</td><td>${x.orders}</td><td class="money">${money(x.revenue)}</td><td>${x.last.split('-').reverse().join('/')}</td></tr>`).join('')+(shown.length?'':'<tr><td colspan="6" class="history-empty">Không có đơn giao thành công trong kỳ này.</td></tr>');$('#report-pagination').innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button class="page-button ${i+1===current?'active':''}" data-page="${i+1}">${i+1}</button>`).join(''):''}
function showCustomerHistory(phone,name){const customer=decodeURIComponent(name||''),orders=data.Orders.filter(x=>(phone?x.CustomerPhone===phone:x.CustomerName===customer)).sort((a,b)=>b.Date.localeCompare(a.Date));$('#modal-title').textContent=`Lịch sử mua hàng – ${customer}`;$('#modal-form').innerHTML='<div class="table-wrap"><table><tr><th>Thời gian</th><th>Sản phẩm</th><th>Số lượng</th><th>Số tiền</th><th>Trạng thái</th></tr>'+orders.map(o=>`<tr><td>${o.Date.split('-').reverse().join('/')}</td><td>${o.Product||'—'}</td><td>${o.Quantity||'—'}</td><td class="money">${money(o.Amount)}</td><td>${o.Status}</td></tr>`).join('')+'</table></div>';$('#modal').classList.remove('hidden')}
function buildDailyReport(){const date=today(),sale=$('#daily-report-sale')?.value||'Tất cả',rows=data.Orders.filter(x=>x.Date===date&&(sale==='Tất cả'||x.Owner===sale)),leads=data.Customers.filter(x=>x.Created===date&&(sale==='Tất cả'||x.Owner===sale)).length,category=x=>{const p=flat(x.Product);return p.includes('curcumin')?'Curcumin':p.includes('badd')||p.includes('bua an')?'BADD':p.includes('fucoidan')?'Fucoidan Pro':x.Product||'Sản phẩm khác'},groups=new Map();rows.forEach(x=>{const type=x.Type==='Khách cũ'?'Khách cũ':x.Type==='Khách mới'?'Khách mới':'Chưa phân loại',key=`${category(x)}|${type}`,item=groups.get(key)||{label:`${category(x)} – ${type}`,orders:0,revenue:0};item.orders++;item.revenue+=+x.Amount||0;groups.set(key,item)});const tableRows=[...(leads?[{label:'Data mới',orders:leads,revenue:null}]:[]),...groups.values()],grossRevenue=sum(rows,'Amount'),title=sale==='Tất cả'?'BÁO CÁO ĐỘI SALE':`BÁO CÁO SALE ${sale.toUpperCase()}`,text=[`${title} – ${date.split('-').reverse().join('/')}`,...tableRows.map(x=>x.revenue===null?`${x.label}: ${x.orders}`:`${x.label}: ${x.orders} đơn – ${money(x.revenue)}`),`TỔNG DOANH THU: ${money(grossRevenue)}`].join('\n\n'),html=`<table class="daily-report-table"><thead><tr><th>${date.split('-').reverse().join('/')}</th><th>Số liệu</th><th>Doanh thu</th></tr></thead><tbody>${tableRows.map(x=>`<tr><td>${x.label}</td><td>${x.orders}</td><td>${x.revenue===null?'—':money(x.revenue)}</td></tr>`).join('')}<tr class="gross-row"><td>Tổng doanh thu</td><td>${rows.length}</td><td>${money(grossRevenue)}</td></tr></tbody></table>`;return {date,sale,text,html}}
function renderSummaryReport(){return buildDailyReport()}
async function openDailyReportForm(){const create=$('#summary-apply'),sale=$('#daily-report-sale').value;create.disabled=true;create.textContent=`Đang tải Sheet ${sale}...`;try{await window.vitagreen.syncReportSale(sale);data=await window.vitagreen.getData()}catch(e){toast('Không thể tải dữ liệu Google Sheet: '+e.message);return}finally{create.disabled=false;create.textContent='Tạo báo cáo hôm nay'}const report=buildDailyReport();$('#modal-title').textContent=`Báo cáo ${report.sale==='Tất cả'?'đội sale':`sale ${report.sale}`} – ${report.date.split('-').reverse().join('/')}`;$('#modal-form').innerHTML=`<p class="report-form-note">Doanh thu gộp là tất cả đơn phát sinh, không phân biệt trạng thái.</p>${report.html}<div class="report-form-actions"><button type="button" id="send-zalo-report" class="primary">Gửi báo cáo</button><button type="button" id="cancel-daily-report">Hủy</button></div>`;$('#modal').classList.remove('hidden');$('#cancel-daily-report').onclick=()=>$('#modal').classList.add('hidden');$('#send-zalo-report').onclick=async()=>{const button=$('#send-zalo-report');button.disabled=true;button.textContent='Đang gửi...';try{const result=await window.vitagreen.sendZaloReport(report);if(result.ok){$('#modal').classList.add('hidden');toast('Đã gửi báo cáo vào nhóm Zalo.')}else toast(result.message||'Chưa thể gửi báo cáo Zalo.')}catch(e){toast('Gửi báo cáo không thành công: '+e.message)}finally{button.disabled=false;button.textContent='Gửi báo cáo'}}}
function renderReports(){const defaultFrom=$('#from').value||'2026-08-01',defaultTo=$('#to').value||today();if(!$('#report-from').value){$('#report-from').value=defaultFrom;$('#report-to').value=defaultTo}renderCustomerReport()}
function form(title,fields,onSave){$('#modal-title').textContent=title;$('#modal-form').innerHTML=fields.map(x=>`<label>${x.label}<${x.type||'input'} name="${x.name}" ${x.type==='select'?'':'type="'+(x.input||'text')+'"'} ${x.required?'required':''}>${x.options?x.options.map(o=>`<option>${o}</option>`).join(''):''}</${x.type||'input'}></label>`).join('')+'<button class="primary" type="submit">Lưu</button>';$('#modal').classList.remove('hidden');$('#modal-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));onSave(v);$('#modal').classList.add('hidden')}}
function id(prefix,items){return prefix+String(items.length+1).padStart(3,'0')}
const careStyle=document.createElement('style');careStyle.textContent='.care-tabs{display:flex;gap:8px;border-bottom:1px solid #dce5f0;margin-bottom:20px}.care-tab{border:0;background:transparent;padding:12px 15px;color:#587095;font-weight:800;cursor:pointer}.care-tab.active{color:#078361;border-bottom:3px solid #078361}.care-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.care-heading h2{margin:0}.care-heading p{margin:5px 0 0;color:#587095}.care-actions{display:flex;align-items:end;gap:12px}.care-actions label{display:grid;gap:5px;color:#587095;font-size:13px}.care-actions select{min-width:180px;border:1px solid #cbd8e8;border-radius:7px;padding:9px;background:#fff;font:inherit;color:#102b50}.note-link{border:0;background:transparent;color:#087c68;font:inherit;text-align:left;cursor:pointer;max-width:230px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.note-history>div{padding:12px;border-bottom:1px solid #e7edf5}.note-history p{margin:6px 0 0}.care-customers-table th,.care-scheduled-table th{white-space:nowrap}';document.head.appendChild(careStyle);
function careRows(){const notes=data.CustomerNotes||[];return [...data.Customers].map(c=>{const orders=data.Orders.filter(o=>o.CustomerPhone===c.Phone).sort((a,b)=>b.Date.localeCompare(a.Date));const latestNote=notes.filter(n=>n.Phone===c.Phone).sort((a,b)=>b.Date.localeCompare(a.Date))[0];return {...c,lastPurchase:orders[0]?.Date||'',latestNote:latestNote?.Text||'',lastCalled:c.LastCalled||''}}).sort((a,b)=>(b.lastPurchase||'').localeCompare(a.lastPurchase||''))}
function calledDayCount(lastCalled){if(!lastCalled)return 0;const days=Math.floor((Date.parse(`${today()}T00:00:00`)-Date.parse(`${lastCalled}T00:00:00`))/86400000);return Math.min(30,Math.max(0,days))}
function renderCarePage(tab='customers'){const page=$('#followups-page');if(!page)return;page.innerHTML=`<article><div class="care-tabs"><button class="care-tab ${tab==='customers'?'active':''}" data-care-tab="customers">Danh sách khách hàng</button><button class="care-tab ${tab==='scheduled'?'active':''}" data-care-tab="scheduled">Khách có hẹn chăm sóc</button></div><div id="care-content"></div></article>`;const content=$('#care-content');if(tab==='customers'){const purchaseFilter=window.carePurchaseFilter||'all',rows=careRows().filter(c=>purchaseFilter==='purchased'?!!c.lastPurchase:purchaseFilter==='not-purchased'?!c.lastPurchase:true);content.innerHTML=`<div class="care-heading"><div><h2>Khách hàng của sale</h2><p>Bấm tên khách để xem hồ sơ, lịch sử đơn và lên đơn mới.</p></div><div class="care-actions"><label>Lọc khách<select id="care-purchase-filter"><option value="all" ${purchaseFilter==='all'?'selected':''}>Tất cả khách hàng</option><option value="purchased" ${purchaseFilter==='purchased'?'selected':''}>Khách đã mua hàng</option><option value="not-purchased" ${purchaseFilter==='not-purchased'?'selected':''}>Khách chưa mua hàng</option></select></label><button class="primary" id="add-followup">+ Hẹn chăm sóc</button></div></div><div class="table-wrap"><table id="care-customers-table"><tr><th>Khách hàng</th><th>Số điện thoại</th><th>Sale</th><th>Gọi</th><th>Ngày gọi gần nhất</th><th>Ngày mua gần nhất</th><th>Ghi chú gần nhất</th></tr>${rows.map(c=>`<tr><td><button class="customer-link care-profile" data-phone="${c.Phone}">${c.Name||'—'}</button></td><td>${c.Phone||'—'}</td><td>${c.Owner||'—'}</td><td><button class="link-btn care-call" data-phone="${c.Phone}">Đã gọi</button></td><td>${c.lastCalled?c.lastCalled.split('-').reverse().join('/'): '—'}</td><td>${c.lastPurchase?c.lastPurchase.split('-').reverse().join('/'): '—'}</td><td>${c.latestNote?`<button class="note-link" data-phone="${c.Phone}">${c.latestNote}</button>`:'—'}</td></tr>`).join('')}</table></div>`;$('#add-followup').onclick=addFollowup}else{const rows=[...(data.FollowUps||[])].sort((a,b)=>a.Due.localeCompare(b.Due));content.innerHTML=`<div class="care-heading"><div><h2>Khách có hẹn chăm sóc</h2><p>Bấm tên khách để xem hồ sơ, lịch sử đơn và lên đơn mới.</p></div><button class="primary" id="add-followup">+ Hẹn chăm sóc</button></div><div class="table-wrap"><table id="care-scheduled-table"><tr><th>Hạn chăm sóc</th><th>Khách hàng</th><th>Số điện thoại</th><th>Sale</th><th>Nội dung</th><th>Trạng thái</th></tr>${rows.map((x,i)=>`<tr><td>${x.Due?.split('-').reverse().join('/')||'—'}</td><td><button class="customer-link care-profile" data-phone="${x.CustomerPhone}">${x.CustomerName||'—'}</button></td><td>${x.CustomerPhone||'—'}</td><td>${x.Owner||'—'}</td><td>${x.Content||'—'}</td><td><select class="follow-status" data-i="${i}"><option ${x.Status==='Chưa liên hệ'?'selected':''}>Chưa liên hệ</option><option ${x.Status==='Đã gọi'?'selected':''}>Đã gọi</option><option ${x.Status==='Không nghe'?'selected':''}>Không nghe</option><option ${x.Status==='Cần gọi lại'?'selected':''}>Cần gọi lại</option><option ${x.Status==='Có nhu cầu'?'selected':''}>Có nhu cầu</option><option ${x.Status==='Đã mua'?'selected':''}>Đã mua</option></select> <button class="link-btn care-save-follow" data-i="${i}">Lưu</button> <button class="link-btn care-delete-follow" data-i="${i}">Xóa</button></td></tr>`).join('')}</table></div>`;$('#add-followup').onclick=addFollowup}page.dataset.careTab=tab}
function markCustomerCalled(phone){const customer=data.Customers.find(c=>c.Phone===phone);if(!customer)return;customer.LastCalled=today();data.CustomerNotes=data.CustomerNotes||[];$('#modal-title').textContent=`Đã gọi – ${customer.Name}`;$('#modal-form').innerHTML=`<label>Ghi chú cuộc gọi<input name="note" placeholder="Nhập ghi chú nếu có"></label><label>Có hẹn chăm sóc lại?<select name="schedule"><option value="no">Không hẹn</option><option value="yes">Có hẹn chăm sóc</option></select></label><label>Ngày hẹn<input name="due" type="date" value="${today()}"></label><label>Nội dung hẹn<input name="content" placeholder="Ví dụ: gọi hỏi tình hình sử dụng"></label><div class="report-form-actions"><button class="primary" type="submit">Lưu</button><button type="button" id="cancel-call">Hủy</button></div>`;$('#modal').classList.remove('hidden');$('#cancel-call').onclick=()=>$('#modal').classList.add('hidden');$('#modal-form').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(v.note?.trim())data.CustomerNotes.push({Id:id('NOTE',data.CustomerNotes),Phone:phone,Text:v.note.trim(),Date:today()});if(v.schedule==='yes'){data.FollowUps=data.FollowUps||[];data.FollowUps.push({Id:id('CS',data.FollowUps),CustomerPhone:phone,CustomerName:customer.Name,Owner:customer.Owner,Due:v.due,Content:v.content||'Chăm sóc lại khách hàng',Status:'Chưa liên hệ'})}save('Đã lưu cuộc gọi'+(v.schedule==='yes'?' và lịch hẹn chăm sóc':'')+'');$('#modal').classList.add('hidden');renderCarePage('customers');renderDashboard()}}
function showNoteHistory(phone){const notes=(data.CustomerNotes||[]).filter(n=>n.Phone===phone).sort((a,b)=>b.Date.localeCompare(a.Date));const c=data.Customers.find(x=>x.Phone===phone);$('#modal-title').textContent=`Lịch sử ghi chú – ${c?.Name||phone}`;$('#modal-form').innerHTML=notes.length?`<div class="note-history">${notes.map(n=>`<div><b>${n.Date.split('-').reverse().join('/')}</b><p>${n.Text}</p></div>`).join('')}</div>`:'<p>Chưa có ghi chú.</p>';$('#modal').classList.remove('hidden')}
function renderCareNotifications(){if(!data)return;const due=(data.FollowUps||[]).filter(x=>x.Due<=today()&&!['Đã mua','Hoàn thành'].includes(x.Status));if(!due.length)return;const notices=window.currentNotices||[];due.forEach(x=>{if(!notices.some(n=>n.kind==='due-followup'&&n.followupId===x.Id))notices.unshift({kind:'due-followup',followupId:x.Id,type:'danger',title:`Đến hạn chăm sóc – ${x.CustomerName}`,text:`Khách ${x.CustomerName} (${x.CustomerPhone}) cần được chăm sóc vào ${x.Due.split('-').reverse().join('/')}. Bấm vào thông báo để mở danh sách hẹn chăm sóc.`,metric:'Lịch chăm sóc',value:x.Due.split('-').reverse().join('/'),target:'Thực hiện trong ngày',solution:x.Content||'Liên hệ lại khách hàng.'})});window.currentNotices=notices;const badge=$('#notification-count');badge.textContent=notices.length;badge.classList.toggle('hidden',data.NotificationsRead||!notices.length);$('#notification-list').innerHTML=notices.map((n,i)=>`<div class="notification-item ${n.type}" data-notice="${i}"><b>${n.title}</b><p>${n.text}</p></div>`).join('')}
const openNoticeBase=openNotice;openNotice=function(index){const n=window.currentNotices?.[index];if(n?.kind==='due-followup'){showPage('followups');renderCarePage('scheduled');$('#notification-panel').classList.add('hidden');return}openNoticeBase(index)};
const renderDashboardBase=renderDashboard;renderDashboard=function(){renderDashboardBase();renderCareNotifications()};
const renderCarePageBase=renderCarePage;renderCarePage=function(tab='customers'){renderCarePageBase(tab);if(tab==='customers'){careRows().forEach(c=>{const button=$(`.care-call[data-phone="${c.Phone}"]`);if(button){const done=c.lastCalled===today(),dayCount=calledDayCount(c.lastCalled);button.textContent=done?'✓ Đã gọi':dayCount?`✓ Đã gọi · ${dayCount} ngày`:'☐';button.classList.toggle('called-today',done);button.classList.toggle('called-history',!done&&dayCount>0);button.title=done?'Đã gọi trong hôm nay':dayCount?`Đã gọi được ${dayCount} ngày${dayCount===30?' (đã dừng cập nhật)':''}`:'Tích để đánh dấu đã gọi'}})}};
const markCustomerCalledBase=markCustomerCalled;markCustomerCalled=function(phone){const customer=data.Customers.find(c=>c.Phone===phone);if(!customer)return;customer.LastCalled=today();window.vitagreen.saveData(data);renderCarePage('customers');markCustomerCalledBase(phone)};
const renderCarePageInteractive=renderCarePage;renderCarePage=function(tab='customers'){renderCarePageInteractive(tab);document.querySelectorAll('.care-profile').forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();showCustomerProfile(button.dataset.phone)});if(tab==='customers'){const filter=$('#care-purchase-filter');if(filter)filter.onchange=()=>{window.carePurchaseFilter=filter.value;renderCarePage('customers')};document.querySelectorAll('.care-call').forEach(button=>button.onclick=e=>{e.preventDefault();e.stopPropagation();markCustomerCalled(button.dataset.phone)})}else{document.querySelectorAll('.follow-status').forEach(select=>{select.addEventListener('mousedown',event=>event.stopPropagation());select.addEventListener('click',event=>event.stopPropagation())})}};
const callStyle=document.createElement('style');callStyle.textContent='.care-call{min-width:82px;font-weight:800}.care-call.called-today{color:#078361;background:#effbf6;border:1px solid #9bd8c5;border-radius:6px;padding:6px 9px}.care-call.called-history{color:#526987;background:#f4f7fb;border:1px solid #d4deeb;border-radius:6px;padding:6px 9px}';document.head.appendChild(callStyle);
renderFollowups=function(){renderCarePage($('#followups-page')?.dataset.careTab||'customers')};
document.addEventListener('click',e=>{const tab=e.target.closest('[data-care-tab]');if(tab){renderCarePage(tab.dataset.careTab);return}const profile=e.target.closest('.care-profile');if(profile){showCustomerProfile(profile.dataset.phone);return}const call=e.target.closest('.care-call');if(call){markCustomerCalled(call.dataset.phone);return}const note=e.target.closest('.note-link');if(note){showNoteHistory(note.dataset.phone);return}const saveFollow=e.target.closest('.care-save-follow');if(saveFollow){const i=+saveFollow.dataset.i,rows=[...(data.FollowUps||[])].sort((a,b)=>a.Due.localeCompare(b.Due)),task=rows[i];if(task){task.Status=document.querySelector(`.follow-status[data-i="${i}"]`).value;save('Đã cập nhật trạng thái chăm sóc');renderCarePage('scheduled');renderDashboard()}return}const deleteFollow=e.target.closest('.care-delete-follow');if(deleteFollow){const i=+deleteFollow.dataset.i,rows=[...(data.FollowUps||[])].sort((a,b)=>a.Due.localeCompare(b.Due)),task=rows[i];if(!task)return;if(!confirm(`Xóa lịch hẹn chăm sóc của ${task.CustomerName}?`))return;data.FollowUps=data.FollowUps.filter(x=>x.Id!==task.Id);save('Đã xóa lịch hẹn chăm sóc');renderCarePage('scheduled');renderDashboard()}});
function addCustomer(){form('Thêm khách hàng',[{label:'Tên khách hàng',name:'Name',required:true},{label:'Số điện thoại',name:'Phone',required:true},{label:'Nguồn',name:'Source'},{label:'Sale phụ trách',name:'Owner',type:'select',options:['Thu','Thủy','Lương','Phương','Chang','Mỹ Anh'],required:true},{label:'Ghi chú',name:'Note'}],v=>{if(data.Customers.some(x=>x.Phone===v.Phone))return toast('Số điện thoại này đã tồn tại');data.Customers.push({Id:id('KH',data.Customers),LeadId:'DATA'+Date.now(),...v,LeadStatus:'Đang tư vấn',Created:today(),PendingLeadSync:true});save('Đã thêm khách hàng thành công');renderCustomers();renderDashboard()})}
function addOrder(){form('Tạo đơn hàng',[{label:'Số điện thoại khách',name:'CustomerPhone',required:true},{label:'Sản phẩm',name:'Product',type:'select',options:['Fucoidan Pro','Bữa ăn dinh dưỡng','Curcumin','Sản phẩm khác'],required:true},{label:'Số lượng',name:'Quantity',input:'number',required:true},{label:'Tổng giá trị',name:'Amount',input:'number',required:true},{label:'Sale phụ trách',name:'Owner',type:'select',options:['Thu','Thủy','Lương','Phương','Chang','Mỹ Anh','Tuyết'],required:true},{label:'Trạng thái',name:'Status',type:'select',options:['Thành công','Hoàn','Hủy'],required:true}],async v=>{const c=data.Customers.find(x=>x.Phone===v.CustomerPhone);if(!c)return toast('Chưa có khách với số điện thoại này. Hãy thêm khách trước.');const prior=data.Orders.some(x=>x.CustomerPhone===v.CustomerPhone&&x.Status==='Thành công');const order={Id:`APP-${Date.now()}`,CustomerPhone:v.CustomerPhone,CustomerName:c.Name,Owner:v.Owner,Product:v.Product,Quantity:+v.Quantity,Amount:+v.Amount,Date:today(),Status:v.Status,Type:prior?'Khách cũ':'Khách mới',PendingSync:false};try{toast('Đang gửi đơn lên VTG_lendon...');await window.vitagreen.appendOrderToSheet(order,c);data.Orders.push(order);save(`Đã gửi đơn lên VTG_lendon của ${v.Owner}. Hệ thống tự phân loại ${order.Type.toLowerCase()}.`);renderOrders();renderDashboard()}catch(error){toast(`Đơn chưa được gửi lên Google Sheet: ${error.message||'Lỗi không xác định.'}`)}})}
function addFollowup(){form('Hẹn chăm sóc khách',[{label:'Số điện thoại khách',name:'CustomerPhone',required:true},{label:'Ngày chăm sóc',name:'Due',input:'date',required:true},{label:'Nội dung',name:'Content',required:true},{label:'Sale phụ trách',name:'Owner',type:'select',options:['Thu','Thủy','Lương','Phương','Chang','Mỹ Anh'],required:true}],v=>{const c=data.Customers.find(x=>x.Phone===v.CustomerPhone);if(!c)return toast('Chưa có khách với số điện thoại này');data.FollowUps.push({Id:id('CS',data.FollowUps),...v,CustomerName:c.Name,Status:'Chưa liên hệ'});save('Đã tạo lịch chăm sóc');renderFollowups();renderDashboard()})}
async function cancelOrder(orderId){const order=data.Orders.find(x=>x.Id===orderId);if(!order)return toast('Không tìm thấy đơn hàng.');if(order.Status==='Hủy'||order.Status==='Hoàn')return;const accepted=confirm(`Hủy đơn ${order.Id} của ${order.CustomerName}? Đơn sẽ được hủy trên app; app cũng sẽ thử cập nhật VTG_lendon nếu còn tìm thấy mã đơn.`);if(!accepted)return;order.Status='Hủy';await window.vitagreen.saveData(data);renderOrders();renderDashboard();try{await window.vitagreen.cancelOrderInSheet(order);toast(`Đã hủy đơn trên app và cập nhật VTG_lendon của ${order.Owner}.`)}catch(error){toast(`Đã hủy đơn trên app. Chưa cập nhật được VTG_lendon: ${error.message||'không tìm thấy mã đơn trên Sheet'}.`)}}
function showPage(page){currentPage=page;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===page+'-page'));document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const title={dashboard:['TỔNG QUAN KINH DOANH','Hiệu quả doanh thu & sale','Dữ liệu đơn hàng, CRM và KPI được tính tự động từ một nguồn duy nhất.'],customers:['CRM KHÁCH HÀNG','Khách hàng & data','Mỗi khách có một hồ sơ; số điện thoại là định danh để không nhập trùng.'],orders:['ĐƠN HÀNG','Đơn hàng & doanh thu','Tạo đơn từ khách có sẵn. Loại khách được nhận diện tự động.'],followups:['CHĂM SÓC KHÁCH','Lịch chăm sóc','Đưa khách đến kỳ mua lại và lịch cần gọi lên đầu công việc.'],reports:['BÁO CÁO','Báo cáo khách hàng','Xem khách hàng doanh thu cao, lịch sử mua hàng và báo cáo tổng hợp theo kỳ.'],settings:['QUẢN TRỊ','Đồng bộ & vận hành','Dữ liệu gốc nằm trong app; Google Sheet là nơi đồng bộ thủ công.']}[page];$('#eyebrow').textContent=title[0];$('#page-title').textContent=title[1];$('#page-description').textContent=title[2];if(page==='customers')renderCustomers();if(page==='orders')renderOrders();if(page==='followups')renderFollowups();if(page==='reports')renderReports()}
function startLogin(){const style=document.createElement('style');style.textContent='.login-overlay{position:fixed;inset:0;z-index:999;background:linear-gradient(135deg,#0d3567,#057b67);display:grid;place-items:center}.login-card{width:400px;background:#fff;border-radius:16px;padding:34px;box-shadow:0 24px 60px rgba(0,0,0,.28)}.login-brand{font-weight:900;font-size:25px;color:#102b50}.login-brand span{display:block;color:#079274;font-size:12px;letter-spacing:2px;margin-top:4px}.login-card h2{margin:28px 0 7px;color:#102b50}.login-card p{color:#587095}.login-tabs{display:flex;gap:8px;margin:24px 0}.login-tabs button{flex:1;border:1px solid #cfdae8;background:#fff;border-radius:7px;padding:10px;font-weight:800;cursor:pointer}.login-tabs button.active{background:#078361;color:#fff;border-color:#078361}.login-card label{display:grid;gap:6px;margin:12px 0;color:#39587f;font-weight:700}.login-card input{border:1px solid #cbd8e8;border-radius:7px;padding:11px;font:inherit}.login-card .primary{width:100%;margin-top:15px}.login-error{min-height:20px;color:#c52646;font-size:13px;margin-top:10px}.login-hidden{display:none!important}';document.head.appendChild(style);const overlay=document.createElement('div');overlay.className='login-overlay';overlay.id='login-overlay';overlay.innerHTML=`<div class="login-card"><div class="login-brand">VITAGREEN<span>CRM & KPI</span></div><h2>Đăng nhập hệ thống</h2><p>Chọn hình thức đăng nhập để tiếp tục.</p><div class="login-tabs"><button class="active" data-login-role="sale">Sale</button><button data-login-role="admin">Admin</button></div><div id="sale-login"><p>Đăng nhập Sale đang là mặc định. Tài khoản từng sale sẽ được thiết lập sau.</p><button id="sale-login-button" class="primary">Đăng nhập Sale</button></div><form id="admin-login" class="login-hidden"><label>Tài khoản<input name="username" autocomplete="username" required></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit">Đăng nhập Admin</button></form><div id="login-error" class="login-error"></div></div>`;document.body.appendChild(overlay);let role='sale';const enter=(name,nextRole)=>{window.currentUser={name,role:nextRole};document.querySelector('.user').innerHTML=`${name}<br><small>${nextRole==='admin'?'Quản trị viên':'Nhân viên sale'}</small>`;overlay.remove();toast(`Đăng nhập thành công: ${name}`)};overlay.querySelectorAll('[data-login-role]').forEach(button=>button.onclick=()=>{role=button.dataset.loginRole;overlay.querySelectorAll('[data-login-role]').forEach(x=>x.classList.toggle('active',x===button));$('#sale-login').classList.toggle('login-hidden',role!=='sale');$('#admin-login').classList.toggle('login-hidden',role!=='admin');$('#login-error').textContent=''});$('#sale-login-button').onclick=()=>enter('Sale','sale');$('#admin-login').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(v.username==='admin'&&v.password==='Tungdeptrai')enter('Admin','admin');else $('#login-error').textContent='Tài khoản hoặc mật khẩu Admin không đúng.'}}
const SALE_LOGIN_ACCOUNTS=[{username:'Luonggia',password:'giaketao',owner:'L\u01b0\u01a1ng'}];
// Phiên này được gửi kèm mỗi thao tác Google Sheet để Gateway xác thực người dùng.
document.addEventListener('submit',event=>{if(!['sale-login','admin-login'].includes(event.target.id))return;const values=Object.fromEntries(new FormData(event.target));const session={username:values.username,password:values.password};setTimeout(()=>{if(window.currentUser)window.currentUser.gatewaySession=session},0)},true);
const gatewayAppendOrder=window.vitagreen.appendOrderToSheet;
const gatewayCancelOrder=window.vitagreen.cancelOrderInSheet;
window.vitagreen.appendOrderToSheet=(order,customer,session)=>gatewayAppendOrder(order,customer,session||window.currentUser?.gatewaySession);
window.vitagreen.cancelOrderInSheet=(order,session)=>gatewayCancelOrder(order,session||window.currentUser?.gatewaySession);
window.activeSaleScope=null;
function currentSaleOwner(){return window.activeSaleScope||(window.currentUser?.role==='sale'?window.currentUser.owner:null)}
function permittedOwner(owner){const mine=currentSaleOwner();return !mine||flat(owner)===flat(mine)}
function scoped(items){return currentSaleOwner()?items.filter(item=>permittedOwner(item.Owner)):items}
function applySaleScope(){const mine=currentSaleOwner(),select=$('#sale');if(select&&mine){const match=[...select.options].find(x=>flat(x.value)===flat(mine));if(match)select.value=match.value;select.disabled=true}if(select&&!mine)select.disabled=false;const settings=$('#nav [data-page="settings"]');if(settings)settings.hidden=!!mine}
startLogin=function(){const css=document.createElement('style');css.textContent='.login-overlay{position:fixed;inset:0;z-index:999;background:linear-gradient(135deg,#0d3567,#057b67);display:grid;place-items:center}.login-card{width:400px;background:#fff;border-radius:16px;padding:32px;box-shadow:0 24px 60px rgba(0,0,0,.28)}.login-card label{display:grid;gap:6px;margin:12px 0;color:#39587f;font-weight:700}.login-card input{border:1px solid #cbd8e8;border-radius:7px;padding:11px;font:inherit}.login-card .primary{width:100%;margin-top:15px}.login-tabs{display:flex;gap:8px;margin:20px 0}.login-tabs button{flex:1;padding:10px;border:1px solid #cfdae8;background:#fff;border-radius:7px;font-weight:800}.login-tabs button.active{background:#078361;color:#fff}.login-hidden{display:none!important}.login-error{min-height:20px;color:#c52646;margin-top:10px}';document.head.appendChild(css);const overlay=document.createElement('div');overlay.className='login-overlay';overlay.innerHTML='<div class="login-card"><b style="font-size:24px;color:#102b50">VITAGREEN</b><h2>Đăng nhập hệ thống</h2><div class="login-tabs"><button class="active" data-role="sale">Sale</button><button data-role="admin">Admin</button></div><form id="sale-login"><label>Tài khoản<input name="username" required></label><label>Mật khẩu<input name="password" type="password" required></label><button class="primary" type="submit">Đăng nhập Sale</button></form><form id="admin-login" class="login-hidden"><label>Tài khoản<input name="username" required></label><label>Mật khẩu<input name="password" type="password" required></label><button class="primary" type="submit">Đăng nhập Admin</button></form><div id="login-error" class="login-error"></div></div>';document.body.appendChild(overlay);let role='sale';const enter=(name,nextRole,owner)=>{window.currentUser={name,role:nextRole,owner};document.querySelector('.user').innerHTML=`${name}<br><small>${nextRole==='admin'?'Quản trị viên':'Nhân viên sale'}</small>`;overlay.remove();applySaleScope();renderDashboard();renderCustomers();renderOrders();renderFollowups();toast(`Đăng nhập thành công: ${name}`)};overlay.querySelectorAll('[data-role]').forEach(button=>button.onclick=()=>{role=button.dataset.role;overlay.querySelectorAll('[data-role]').forEach(x=>x.classList.toggle('active',x===button));$('#sale-login').classList.toggle('login-hidden',role!=='sale');$('#admin-login').classList.toggle('login-hidden',role!=='admin');$('#login-error').textContent=''});$('#sale-login').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target)),account=SALE_LOGIN_ACCOUNTS.find(x=>x.username===v.username&&x.password===v.password);if(account)enter(account.owner,'sale',account.owner);else $('#login-error').textContent='Tài khoản hoặc mật khẩu Sale không đúng.'};$('#admin-login').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(v.username==='admin'&&v.password==='Tungdeptrai')enter('Admin','admin',null);else $('#login-error').textContent='Tài khoản hoặc mật khẩu Admin không đúng.'}};
function activateAccessControl(){const originalFiltered=filtered;filtered=function(){return scoped(originalFiltered())};const originalDashboard=renderDashboard;renderDashboard=function(){applySaleScope();originalDashboard();const mine=currentSaleOwner();if(!mine)return;const rows=filtered(),metrics=kpi(rows),lead=data.Customers.filter(x=>permittedOwner(x.Owner)&&x.Created>=$('#from').value&&x.Created<=$('#to').value).length;$('#ranking').innerHTML=`<div class="rank-row"><span>#1 ${mine}</span><div class="rank-bar"><div class="rank-fill" style="width:100%"></div></div><b>${money(metrics.revenue)}</b></div>`;$('#performance').innerHTML='<tr><th>Sale</th><th>DT khách mới</th><th>DT khách cũ</th><th>Tổng DT</th><th>Data</th><th>Đơn mới</th><th>Đơn cũ</th><th>Tỷ lệ chốt</th><th>AOV</th><th>Hoàn</th></tr>'+`<tr><td><b>${mine}</b></td><td>${money(metrics.newRev)}</td><td>${money(metrics.oldRev)}</td><td>${money(metrics.revenue)}</td><td>${lead}</td><td>${metrics.n.length}</td><td>${metrics.o.length}</td><td>${lead?Math.round(metrics.n.length/lead*100)+'%':'—'}</td><td>${money((metrics.newRev+metrics.oldRev)/Math.max(1,metrics.n.length+metrics.o.length))}</td><td>${metrics.r.length}</td></tr>`};renderCustomers=function(){const q=($('#customer-search').value||'').toLowerCase(),rows=scoped(data.Customers).filter(x=>!q||x.Name.toLowerCase().includes(q)||x.Phone.includes(q));$('#customers-table').innerHTML='<tr><th>Khách hàng</th><th>Số điện thoại</th><th>Nguồn</th><th>Sale phụ trách</th><th>Ngày tạo</th><th>Ghi chú</th></tr>'+rows.sort((a,b)=>b.Created.localeCompare(a.Created)).map(x=>`<tr><td><button class="customer-link customer-profile" data-phone="${x.Phone}">${x.Name}</button></td><td>${x.Phone}</td><td>${x.Source||'—'}</td><td>${x.Owner}</td><td>${x.Created}</td><td>${x.Note||'—'}</td></tr>`).join('')};renderOrders=function(){const rows=scoped(data.Orders).sort((a,b)=>b.Date.localeCompare(a.Date));$('#orders-table').innerHTML='<tr><th>Ngày</th><th>Khách hàng</th><th>Sale</th><th>Sản phẩm</th><th>SL</th><th>Giá trị</th><th>Loại khách</th><th>Trạng thái</th></tr>'+rows.map(x=>{const canCancel=!['huy','hoan'].includes(flat(x.Status));return `<tr><td>${x.Date}</td><td><b>${x.CustomerName}</b><br><small>${x.CustomerPhone}</small></td><td>${x.Owner}</td><td>${x.Product}</td><td>${x.Quantity}</td><td class="money">${money(x.Amount)}</td><td>${x.Type}</td><td>${x.Status}${canCancel?`<br><button class="link-btn cancel-order" data-order-id="${x.Id}">Hủy đơn</button>`:''}</td></tr>`}).join('')};const originalCareRows=careRows;careRows=function(){return scoped(originalCareRows())};const originalProfile=showCustomerProfile;showCustomerProfile=function(phone){const customer=data.Customers.find(x=>x.Phone===phone);if(customer&&!permittedOwner(customer.Owner))return toast('Bạn không có quyền xem khách hàng của sale khác.');return originalProfile(phone)};const originalOrderForCustomer=openOrderForCustomer;openOrderForCustomer=function(customer){if(!permittedOwner(customer.Owner))return toast('Bạn không có quyền tạo đơn cho khách hàng của sale khác.');originalOrderForCustomer(customer);lockOwner()};function lockOwner(){const mine=currentSaleOwner(),select=$('#modal-form [name="Owner"]');if(mine&&select){const option=[...select.options].find(x=>flat(x.value)===flat(mine));if(option)select.value=option.value;select.style.pointerEvents='none';select.tabIndex=-1}}const originalAddCustomer=addCustomer;addCustomer=function(){originalAddCustomer();lockOwner()};const originalAddOrder=addOrder;addOrder=function(){originalAddOrder();lockOwner()};const originalAddFollowup=addFollowup;addFollowup=function(){originalAddFollowup();lockOwner()};const originalCancel=cancelOrder;cancelOrder=function(orderId){const order=data.Orders.find(x=>x.Id===orderId);if(order&&!permittedOwner(order.Owner))return toast('Bạn không có quyền hủy đơn của sale khác.');return originalCancel(orderId)};const originalCustomerReport=renderCustomerReport;renderCustomerReport=function(page){if(!currentSaleOwner())return originalCustomerReport(page);const orders=data.Orders;data.Orders=scoped(orders);try{return originalCustomerReport(page)}finally{data.Orders=orders}};const originalDailyReport=buildDailyReport;buildDailyReport=function(){if(!currentSaleOwner())return originalDailyReport();const orders=data.Orders,customers=data.Customers;data.Orders=scoped(orders);data.Customers=scoped(customers);try{return originalDailyReport()}finally{data.Orders=orders;data.Customers=customers}}}
document.addEventListener('submit',e=>{if(e.target.id==='sale-login')setTimeout(()=>{if(window.currentUser?.role==='sale'){window.activeSaleScope=window.currentUser.owner;applySaleScope();renderDashboard();renderCustomers();renderOrders();renderFollowups()}},0);if(e.target.id==='admin-login')window.activeSaleScope=null});
function bindAccessEvents(){$('#customer-search').oninput=()=>renderCustomers();$('#add-customer').onclick=()=>addCustomer();$('#add-order').onclick=()=>addOrder();$('#add-followup').onclick=()=>addFollowup()}
setTimeout(activateAccessControl,0);
setTimeout(bindAccessEvents,0);
setTimeout(startLogin,0);
async function init(){data=await window.vitagreen.getData();$('#sale').innerHTML='<option>Tất cả</option>'+SALE_NAMES.map(x=>`<option>${x}</option>`).join('');const dates=(data.Orders||[]).map(x=>x.Date).filter(Boolean).sort(),latest=dates[dates.length-1]||today();$('#from').value=dates[0]||latest;$('#to').value=latest;renderDashboard();renderCustomers();renderOrders();renderFollowups()}
async function syncFromSheet(){try{toast('Đang đồng bộ dữ liệu từ Google Sheet...');const r=await window.vitagreen.syncGoogle();await init();toast(`Đã đồng bộ ${r.orders} đơn từ ${r.sales} link sale.${r.failed?` ${r.failed} sheet chưa đọc được.`:''}`)}catch(e){toast('Đồng bộ không thành công: '+(e.message||'Vui lòng kiểm tra Internet và quyền xem Sheet.'))}}
function showCustomerProfile(phone){const customer=data.Customers.find(x=>x.Phone===phone);if(!customer)return;const orders=data.Orders.filter(x=>x.CustomerPhone===phone).sort((a,b)=>b.Date.localeCompare(a.Date));const total=sum(orders,'Amount');$('#modal-title').textContent=`Hồ sơ khách hàng – ${customer.Name}`;$('#modal-form').innerHTML=`<div class="customer-profile-summary"><p><b>Số điện thoại:</b> ${customer.Phone}</p><p><b>Sale phụ trách:</b> ${customer.Owner||'—'}</p><p><b>Tổng số đơn:</b> ${orders.length} · <b>Tổng giá trị:</b> ${money(total)}</p></div><h3>Lịch sử đơn hàng</h3><div class="table-wrap"><table><tr><th>Ngày</th><th>Sản phẩm</th><th>SL</th><th>Giá trị</th><th>Loại khách</th><th>Trạng thái</th></tr>${orders.length?orders.map(o=>`<tr><td>${o.Date.split('-').reverse().join('/')}</td><td>${o.Product||'—'}</td><td>${o.Quantity||'—'}</td><td class="money">${money(o.Amount)}</td><td>${o.Type||'—'}</td><td>${o.Status||'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="history-empty">Khách chưa có đơn hàng.</td></tr>'}</table></div><div class="report-form-actions"><button type="button" class="primary" id="create-order-for-customer">+ Tạo đơn hàng</button><button type="button" id="close-customer-profile">Đóng</button></div>`;$('#modal').classList.remove('hidden');$('#close-customer-profile').onclick=()=>$('#modal').classList.add('hidden');$('#create-order-for-customer').onclick=()=>openOrderForCustomer(customer)}
function openOrderForCustomer(customer){const ownerOptions=['Thu','Thủy','Lương','Phương','Chang','Mỹ Anh','Tuyết'].map(owner=>`<option ${owner===customer.Owner?'selected':''}>${owner}</option>`).join('');$('#modal-title').textContent=`Tạo đơn hàng – ${customer.Name}`;$('#modal-form').innerHTML=`<label>Số điện thoại khách<input name="CustomerPhone" value="${customer.Phone}" readonly></label><label>Sản phẩm<select name="Product" required><option>Fucoidan Pro</option><option>Bữa ăn dinh dưỡng</option><option>Curcumin</option><option>Sản phẩm khác</option></select></label><label>Số lượng<input name="Quantity" type="number" min="1" value="1" required></label><label>Tổng giá trị<input name="Amount" type="number" min="0" required></label><label>Sale phụ trách<select name="Owner" required>${ownerOptions}</select></label><label>Trạng thái<select name="Status" required><option>Đã lên đơn</option><option>Thành công</option><option>Hoàn</option><option>Hủy</option></select></label><div class="report-form-actions"><button class="primary" id="send-order-sheet" type="submit">Gửi đơn lên Google Sheet</button><button type="button" id="cancel-customer-order">Hủy</button></div>`;$('#cancel-customer-order').onclick=()=>showCustomerProfile(customer.Phone);$('#modal-form').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));const prior=data.Orders.some(x=>x.CustomerPhone===customer.Phone&&x.Status==='Thành công');const order={Id:`APP-${Date.now()}`,CustomerPhone:customer.Phone,CustomerName:customer.Name,Owner:v.Owner,Product:v.Product,Quantity:+v.Quantity,Amount:+v.Amount,Date:today(),Status:v.Status,Type:prior?'Khách cũ':'Khách mới',PendingSync:false};const button=$('#send-order-sheet');button.disabled=true;button.textContent='Đang gửi lên Google Sheet...';try{await window.vitagreen.appendOrderToSheet(order,customer);data.Orders.push(order);await window.vitagreen.saveData(data);toast(`Đã gửi đơn lên VTG_lendon của ${v.Owner}.`);$('#modal').classList.add('hidden');renderOrders();renderCustomers();renderDashboard()}catch(error){toast(`Đơn chưa được gửi lên Google Sheet: ${error.message||'Lỗi không xác định.'}`);button.disabled=false;button.textContent='Gửi đơn lên Google Sheet'}}}
async function updateSoftware(){const buttons=[$('#software-update'),$('#settings-update')].filter(Boolean);try{buttons.forEach(button=>{button.disabled=true;button.textContent='Đang tải bộ cài...'});const r=await window.vitagreen.checkUpdate();if(!r.available){toast('App đang là phiên bản mới nhất.');return}if(!confirm(`Đã có ${r.version}. Tải và mở bộ cài cập nhật ngay?`))return;buttons.forEach(button=>button.textContent='Đang mở bộ cài...');const result=await window.vitagreen.installUpdate();if(result.available)toast(`Đã mở bộ cài ${result.version}. Hãy hoàn tất các bước cài đặt của Windows.`)}catch(e){toast('Không thể cập nhật: '+(e.message||'Vui lòng thử lại.'))}finally{buttons.forEach(button=>{button.disabled=false;button.textContent='⇧ Cập nhật phần mềm'})}}
$('#apply').onclick=()=>{dailyPage=1;renderDashboard()};const dailyPager=$('#daily-pagination');if(dailyPager)dailyPager.onclick=e=>{const button=e.target.closest('[data-daily-page]');if(button){dailyPage=+button.dataset.dailyPage;renderDashboard()}};$('#sync-sheet').onclick=syncFromSheet;$('#settings-sync').onclick=syncFromSheet;$('#software-update').onclick=updateSoftware;$('#settings-update').onclick=updateSoftware;$('#notification-bell').onclick=e=>{e.stopPropagation();$('#notification-panel').classList.toggle('hidden')};$('#mark-notifications-read').onclick=e=>{e.stopPropagation();data.NotificationReadDate=today();data.NotificationsRead=true;window.vitagreen.saveData(data);$('#notification-count').classList.add('hidden');toast('Đã đánh dấu thông báo là đã đọc.')};$('#notification-list').onclick=e=>{const item=e.target.closest('[data-notice]');if(item){$('#notification-panel').classList.add('hidden');openNotice(+item.dataset.notice)}};document.addEventListener('click',e=>{if(!e.target.closest('.notification-wrap'))$('#notification-panel').classList.add('hidden')});$('#nav').onclick=e=>{if(e.target.dataset.page)showPage(e.target.dataset.page)};$('#customer-search').oninput=renderCustomers;$('#add-customer').onclick=addCustomer;$('#add-order').onclick=addOrder;$('#add-followup').onclick=addFollowup;$('#close-modal').onclick=()=>$('#modal').classList.add('hidden');$('#customers-table').onclick=e=>{const customer=e.target.closest('.customer-profile');if(customer)showCustomerProfile(customer.dataset.phone)};$('#followups-table').onclick=e=>{if(e.target.classList.contains('done-follow')){const i=+e.target.dataset.i;data.FollowUps[i].Status=document.querySelector(`.follow-status[data-i="${i}"]`).value;save('Đã cập nhật trạng thái chăm sóc');renderFollowups();renderDashboard()}};init();
